example_code:
// Sequelize: model defined in code
const { DataTypes } = require('sequelize');
const User = sequelize.define('User', {
  name: DataTypes.STRING,
  email: { type: DataTypes.STRING, unique: true },
});

async function createUserSequelize(name, email) {
  return User.create({ name, email });
}

// Prisma: model defined in schema.prisma, client is generated
// schema.prisma:
//   model User {
//     id    Int    @id @default(autoincrement())
//     name  String
//     email String @unique
//   }

const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function createUserPrisma(name, email) {
  return prisma.user.create({ data: { name, email } });
}

example_output:
// Sequelize
createUserSequelize('Alice', 'alice@example.com')
-> User { id: 1, name: 'Alice', email: 'alice@example.com' }

// Prisma
createUserPrisma('Bob', 'bob@example.com')
-> { id: 1, name: 'Bob', email: 'bob@example.com' }
